#include "unity.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_peekAt_invalid_negative_position(void) {
    // Setup: Initialize stack to empty state
    initStack();
    // Stack is empty, st.top = -1
    // Choose pos = -1 which satisfies pos < 0
    int pos = -1;

    // Test: call peekAt with invalid negative position
    char result = peekAt(pos);

    // Assertions: Should return null character
    TEST_ASSERT_EQUAL_CHAR('\0', result);
}

void unit_test_peekAt_invalid_position_beyond_top(void) {
    // Setup: Initialize stack and push some items
    initStack();
    // Push a few characters to set st.top
    push('a');
    push('b');
    push('c');
    // After 3 pushes, st.top = 2 (0-based index)
    // Choose pos = 5 which satisfies pos > st.top
    int pos = 5;

    // Test: call peekAt with position beyond current top
    char result = peekAt(pos);

    // Assertions: Should return null character
    TEST_ASSERT_EQUAL_CHAR('\0', result);

    // Cleanup: reset stack for other tests
    initStack();
}

void unit_test_peekAt_invalid_position_empty_stack(void) {
    // Setup: Initialize stack to empty state
    initStack();
    // Stack is empty, st.top = -1
    // Choose pos = 0 which satisfies pos > st.top (0 > -1)
    int pos = 0;

    // Test: call peekAt with position 0 on empty stack
    char result = peekAt(pos);

    // Assertions: Should return null character
    TEST_ASSERT_EQUAL_CHAR('\0', result);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_peekAt_invalid_negative_position);
    RUN_TEST(unit_test_peekAt_invalid_position_beyond_top);
    RUN_TEST(unit_test_peekAt_invalid_position_empty_stack);
    return UNITY_END();
}
